function notify(msg){const el=document.querySelector('#toast');el.textContent=msg;el.style.opacity='1';clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.style.opacity='.72',3600)}
function refresh(){document.querySelector('#level').textContent=String(level).padStart(2,'0');document.querySelector('#xpText').textContent=`${xp} / 100 XP`;document.querySelector('#xpFill').style.width=xp+'%';document.querySelector('#questCount').textContent=`${Math.min(caught,3)} / 3`;document.querySelector('#questFill').style.width=Math.min(100,caught/3*100)+'%';document.querySelector('#partyCount').textContent=`${party.length} / 6`;document.querySelector('#orbCount').textContent=inventory.orbs;document.querySelector('#party').innerHTML=party.length?party.map((p,i)=>`<div class="mon-row"><div class="mon-avatar" style="background:${p.sp.color}33">${p.sp.icon}</div><div class="mon-info"><div class="mon-name">${p.sp.name}</div><div class="mon-level">LV. ${p.level} · ${p.sp.type}</div><div class="hp-track"><div class="hp-fill" style="width:${Math.max(3,p.hp/p.max*100)}%;background:${p.hp<p.max*.3?'#df8b64':''}"></div></div></div><span class="type-pill">${p.hp}/${p.max} HP</span></div>`).join(''):'<div class="empty-party">Your journey starts here.<br>Explore the tall grass!</div>'}
function showModal(html){document.querySelector('#modal').innerHTML=html;document.querySelector('#overlay').classList.add('show')}
function closeModal(){document.querySelector('#overlay').classList.remove('show');encounter=null}
function xpGain(n){xp+=n;while(xp>=100){xp-=100;level++;notify(`Ranger level up! You reached level ${level}.`)}refresh()}
function encounterStart(sp){if(encounter)return;encounter={sp,hp:sp.hp,max:sp.hp,turn:0};renderEncounter()}
function renderEncounter(note=''){let e=encounter;if(!e)return;let rate=Math.round((.25+(1-e.hp/e.max)*.52+(inventory.berries?0.08:0))*100);showModal(`<div class="modal-head"><div class="modal-title">A wild friend appeared!</div><button class="close" onclick="window.closeModal()">×</button></div><div class="encounter"><div class="enc-label">${e.sp.name}</div><div class="enc-level">WILD · LV. ${2+Math.floor(rand()*4)}</div><div class="enc-mon">${e.sp.icon}</div></div><div class="quest-progress" style="margin:0 2px 6px"><span class="eyebrow">VIGOR</span><div class="hp-track" style="flex:1;height:7px"><div class="hp-fill" style="width:${e.hp/e.max*100}%;background:#82b771"></div></div><span class="quest-count">${e.hp}/${e.max}</span></div><div class="battle-log">${note||`A curious ${e.sp.name} is watching you. What will you do?`}</div><div class="enc-actions"><button class="enc-btn primary" onclick="window.throwOrb()">🔮 &nbsp;Use Moon Orb (${inventory.orbs})</button><button class="enc-btn secondary" onclick="window.tussle()">🥊 &nbsp;Gentle tussle</button><button class="enc-btn secondary" onclick="window.feedBerry()">🍓 &nbsp;Offer berry (${inventory.berries})</button><button class="enc-btn secondary" onclick="window.runAway()">🌾 &nbsp;Give space</button></div><div class="catch-rate">ESTIMATED BOND CHANCE &nbsp;·&nbsp; ${rate}%</div>`)}
window.closeModal=closeModal;window.throwOrb=()=>{if(!encounter)return;if(!inventory.orbs){renderEncounter('You are out of Moon Orbs. Visit the grove kiosk later!');return}inventory.orbs--;let chance=.25+(1-encounter.hp/encounter.max)*.52+(encounter.fed?.17:0);if(rand()<chance){let sp=encounter.sp;sp.hidden=true;if(party.length<6){party.push({sp,level:2+Math.floor(rand()*4),hp:sp.hp,max:sp.hp})}caught++;found[sp.name]=(found[sp.name]||0)+1;xpGain(22);refresh();closeModal();notify(`${sp.name} trusts you now! A new friend joined your party.`);document.querySelector('#feedLine').innerHTML=`<strong>You</strong> befriended a wild ${sp.name}!`}else{encounter.hp=Math.max(1,encounter.hp-2);renderEncounter('The Moon Orb wobbled... almost! The wild friend is a little more tired.')}refresh()};
window.tussle=()=>{if(!encounter)return;encounter.hp=Math.max(1,encounter.hp-Math.ceil(4+Math.random()*5));encounter.turn++;renderEncounter(`A gentle tussle! ${encounter.sp.name} is tired, but still curious.`)};
window.feedBerry=()=>{if(!encounter)return;if(!inventory.berries){renderEncounter('You have no berries left.');return}inventory.berries--;encounter.fed=true;encounter.hp=Math.max(1,encounter.hp-2);renderEncounter(`${encounter.sp.name} happily nibbles the berry. It trusts you more!`);refresh()};window.runAway=()=>{if(encounter?.sp)encounter.sp.hidden=false;closeModal();notify('You waved goodbye and continued along the trail.')};
function interact(){if(encounter)return;let nearBerry=berries.find(b=>!b.taken&&Math.hypot(player.x-b.x,player.y-b.y)<46);if(nearBerry){nearBerry.taken=true;if(nearBerry.rare){inventory.berries++;notify('A rare moonberry! It sparkles in your hand.')}else{inventory.berries++;notify('You gathered a wild berry. Useful for making friends!')}refresh();return}let nearWild=wild.find(w=>!w.hidden&&Math.hypot(player.x-w.x,player.y-w.y)<82);if(nearWild){encounterStart(nearWild.sp);return}let npc=players.find(p=>Math.hypot(player.x-p.x,player.y-p.y)<75);if(npc){const lines=[`“The little ones love the flower patches,” says ${npc.name}.`,`“I saw a Glimmeray near the pond!” ${npc.name} waves.`,`“Moon Orbs work best when a friend feels safe,” ${npc.name} says.`];notify(lines[Math.floor(rand()*lines.length)]);return}showToastHelp()}
function showToastHelp(){notify('Tip: wander through the tall grass to meet a wild friend. Press E near berries to gather them.')}
function distanceToTree(x,y){return trees.some(t=>Math.hypot(x-t.x*T,y-(t.y-.15)*T)<T*.52*t.size)}
function step(now){let dt=Math.min(.04,(now-last)/1000||0);last=now;let dx=0,dy=0;if(!document.querySelector('#overlay').classList.contains('show')){if(keys.has('ArrowUp')||keys.has('w'))dy--;if(keys.has('ArrowDown')||keys.has('s'))dy++;if(keys.has('ArrowLeft')||keys.has('a'))dx--;if(keys.has('ArrowRight')||keys.has('d'))dx++;}if(dx||dy){let len=Math.hypot(dx,dy);dx/=len;dy/=len;player.face=Math.abs(dx)>Math.abs(dy)?(dx>0?'right':'left'):(dy>0?'down':'up');let nx=clamp(player.x+dx*player.speed*dt,18,W*T-18),ny=clamp(player.y+dy*player.speed*dt,18,H*T-18);if(!distanceToTree(nx,player.y))player.x=nx;if(!distanceToTree(player.x,ny))player.y=ny;walk+=dt;
// Random wildlife introductions happen in grass, with a gentle cooldown.
if(!encounter&&now>(player.nextMeet||0)&&!isPath(player.x/T,player.y/T)&&rand()<dt*.105){let w=wild.find(x=>!x.hidden&&Math.hypot(x.x-player.x,x.y-player.y)<150);if(w){player.nextMeet=now+8000;encounterStart(w.sp)}}}for(const p of players){p.phase+=dt*.7;if(rand()<dt*.035){p.dx=(rand()-.5)*18;p.dy=(rand()-.5)*18}p.x=clamp(p.x+p.dx*dt,2*T,(W-2)*T);p.y=clamp(p.y+p.dy*dt,2*T,(H-2)*T)}requestAnimationFrame(step)}requestAnimationFrame(step);
document.addEventListener('keydown',e=>{let k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(k==='e'||k===' ')interact();if(k==='escape')closeModal();keys.add(k)});document.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());
document.querySelectorAll('.touchpad button').forEach(b=>{let dir=b.dataset.dir,k={up:'w',down:'s',left:'a',right:'d'}[dir];b.addEventListener('pointerdown',e=>{e.preventDefault();keys.add(k);b.setPointerCapture(e.pointerId)});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys.delete(k)))});
document.querySelector('#overlay').addEventListener('click',e=>{if(e.target.id==='overlay')closeModal()});

